quests[51581] = { id = 51581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerite Mining" }
quests[51582] = { id = 51582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make it Mildenhall", description = "You've no doubt enjoyed a mug or three of world-famous Mildenhall Mead in your local tavern. Today is your day to become a part of the official meadery of Stormsong Valley!\n\nIdeal applicants have a hunger for craft mead, honey, and boundless innovation. Military experience recommended, but not required.\n\nMust not be allergic to bees.\n\nMildenhall Mead - Make it Mildenhall.", completion = "<Ancel is nearly hysterical.>", objectives = "Speak with Ancel Mildenhall at the Mildenhall Meadery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51583] = { id = 51583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerite Wounds" }
