quests[51585] = { id = 51585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quit Your Witchin'" }
quests[51586] = { id = 51586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerite Empowerment" }
quests[51587] = { id = 51587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onward!", description = "I'm glad you came, {name}. With your help, we will show these Kul Tiran dogs what happens when you face a cornered beast!\n\nWarfang Hold is just up the path from here. Come, I'll fill you in on the details.", completion = "I thought I was going to meet the Earthmother along with the rest of my men.", objectives = "Accompany Rexxar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51588] = { id = 51588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familiar Foes" }
quests[51589] = { id = 51589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Kul Tiran Will", description = "Our partnership with the Zandalari will soon be secured. Took a little longer than I expected... but such is the way of things.\n\nUnfortunately, the Alliance seems intent on securing a naval force of their own. That can't be allowed to happen.\n\nWe set sail for Tiragarde Sound when you're ready.", completion = "We're here. Now, to cause a bit of trouble for the locals.\n\n<Nathanos looks at you, then at the rest of the group.>\n\nWe don't look too conspicuous, do we?", objectives = "Sail to Tiragarde Sound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51590] = { id = 51590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Heart of Tiragarde", description = "Step one is to establish a more suitable base of operations. A pirate's den will do in a pinch, but I believe the warchief expects better of us.\n\nLet's split up and push farther inland, to the west. Be on the lookout for something defensible and inconspicuous.", completion = "<Nathanos peers around the corner at the Kul Tiran roughneck camp.>\n\nThis will do. Not only is it well-hidden in the forest, but the locals seem to be rather dull and easily outwitted.", objectives = "Rendezvous with Nathanos and Lilian in central Tiragarde Sound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51591] = { id = 51591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Mountain Now", description = "{name}, go take care of those \"roughnecks.\" They might fashion themselves as tough, but a bit of your unique brand of Horde savagery should have them running in no time.\n\nLilian, scout the area. We need to know about any nearby threats.\n\nRangers, secure the perimeter. We'll reconvene in the roughneck camp once {name}'s work is done.", progress = "Me? I'll go where I'm needed.", completion = "<Nathanos looks around the camp and nods to himself.>\n\nThis will do.", objectives = "Slay 10 Roughnecks in Timberfell Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51592] = { id = 51592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Ourselves at Home", description = "Log cabins will do in a pinch, but... if we're going to be spending any time here, we might as well make ourselves comfortable.\n\nThe roughnecks left us no shortage of lumber and food supplies, but we'll need canvas and chains to set up some proper Forsaken tents and banners. Bridgeport sounds rather lootable, doesn't it?", progress = "With a name like Bridgeport, I have to assume that the town has plenty of supplies in transit, ready for looting.", completion = "I'll have the rangers start working with these right away.", objectives = "Obtain 7 Lengths of Chain and 7 bolts of Sail Canvas from the outskirts of Bridgeport.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51593] = { id = 51593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bridgeport Investigation", description = "While you're in Bridgeport, you might keep an ear out for any information that will be of aid to us.\n\nYou'd be surprised what you can learn by staying quiet and listening to people who think they're alone...", completion = "Explosives in the Ashvane Foundry? Clearly we can put that information to use. Well done.\n\nIt sounds like that Captain Stone is somewhat of a big-shot as well. It would be a shame if something were to happen to her...", objectives = "Spy on the denizens of Bridgeport.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51594] = { id = 51594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosives in the Foundry", description = "I'm most interested in those explosives, though.\n\nMeet me in the foundry, east of here. You probably passed through it on your way from Plunder Harbor.", completion = "<Lilian gestures toward a pile of crates nearby.>\n\nThink those are filled with the explosives?", objectives = "Meet Lilian Voss at the Ashvane Foundry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51595] = { id = 51595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosivity", description = "I don't want to waste your time. Let's make absolutely sure that these are what we're looking for.\n\nHere, take this torch and toss it over onto those crates. If they explode, then we'll know what to do next.", progress = "Well?", completion = "I... ah... I guess we've found our gunpowder then.", objectives = "Use Lilian's Torch on the Pile of Ashvane Crates near the Ashvane Foundry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51596] = { id = 51596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ammunition Acquisition", description = "First: we get as much of that gunpowder as we possibly can. Imagine the terror in the Kul Tirans' eyes when they realize the Horde has turned their own weapons against them.\n\nImagine it, {name}.\n\n<Lilian's eyes briefly glaze over, and the corner of her lips turns upward in a half-smile.>", progress = "I've managed to round up a few crates myself. How did you do?", completion = "Excellent.", objectives = "Obtain 8 crates of Ashvane Explosives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51597] = { id = 51597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gunpowder Research", description = "I suppose that, before we steal all the Kul Tirans' violently explosive gunpowder and use it against them, we should learn how they make the stuff.", progress = "Let's see the paperwork.", completion = "<Lilian quickly looks over the documents and nods.>\n\nI suppose that someone in the Horde will find this information useful.\n\nProbably goblins.", objectives = "Obtain the Ashvane Explosives Formula and the Gunpowder Manufacturing Guide.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51598] = { id = 51598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bit of Chaos", description = "This place seems fairly well-defended for a manufacturing facility, doesn't it?\n\n<Lilian shrugs.>\n\nI suppose we'll have to kill them, then.", completion = "<Lilian bounces her blade in her hands, looks up, and nods approvingly at you.>", objectives = "Slay 15 workers at the Ashvane Foundry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51599] = { id = 51599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death Trap", description = "We started this mission with a goal, but not much of a plan. I think I can see the pieces coming together, though.\n\n<Lilian surveys the horizon, thinking.>\n\nPlace these explosives over on the southwest edge of town. Somewhere inconspicuous.\n\nWe'll meet again over there. In the meantime... I need to find a horse.", completion = "Lucky for us, horses are in no short supply around here.\n\nYou placed the gunpowder?", objectives = "Place 8 Gunpowder Crates in a hidden location southwest of Bridgeport.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51601] = { id = 51601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bridgeport Ride", description = "Pay attention, {name}, because this isn't going to be our standard assassination mission.\n\nYou and I are going to take this horse through Bridgeport and... cause a scene. I want every single guard on our tail, along with that Captain Stone character. Once we've rounded them up, it's over to those explosives, and...\n\n<Lilian's eyes grow wide with delight.>\n\nBoom.", completion = "I heard the blast from up here. I think I may have even gotten a piece of guard on my cloak.", objectives = "Mount the Stolen Horse, then use it to round up 10 Bridgeport Guards and Captain Stone. Then escort them to the southwest corner of town.\n\nGetting knocked off of your horse could prove fatal, and will fail the mission.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51602] = { id = 51602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bandit Blades", description = "We only have enough weapons to arm half of de tribe against Mojambo's gang.\n\nWe're going to need more weapons if we are going to survive de approaching battle.\n\nTongo's crew is sure to have a ready supply of weapons at their hideout.\n\nSearch de hideout for any weapons you can find and bring dem back to de arena.", progress = "Do you have de weapons?", completion = "Dese ancient blades may not be in de best condition, but dey are finely forged. I am sure dey will hold up in battle just fine.", objectives = "Retrieve 8 Sandworn Blades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
