quests[51643] = { id = 51643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wall of Iron", description = "The enemy has pushed our men to the shore and sunk their ships. They have nowhere to run and nowhere to hide; it's up to us to save them!\n\nGet below deck, man a cannon, and start laying down some covering fire. They're depending on us!", completion = "Good job, that'll buy our troops some breathing room.", objectives = "Man a cannon and slay 40 Kul Tiran forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
