quests[51667] = { id = 51667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Bird You Cannot Change" }
quests[51668] = { id = 51668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mojambo", description = "Mojambo and his gang are attacking!\n\nWe must defend de arena. Mojambo must be defeated! De outcasts will take care of his gang. Mojambo is all yours...\n\nBring Tongo's head with you and use it to challenge Mojambo to a duel. His pride is too great to resist such a challenge!", progress = "Mojambo must be defeated!", completion = "At last dis war be over and we can live in peace. I do not know how to thank you for all you've done.", objectives = "Slay Mojambo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51669] = { id = 51669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Black-Eyed Bart" }
