quests[51671] = { id = 51671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Billy Goat Barber", objectives = "Use the Goat Shears on 6 Gentle Goats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51672] = { id = 51672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tangled Webs" }
quests[51674] = { id = 51674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Douse the Flames", description = "Do you smell it, {name}? Smoke! They're burning down Warfang Hold!\n\nThere is little point to our battle if our base burns to the ground!\n\nTheir tidesages use wands to control their constructs of water. In our hands they may give us a chance to save the Hold! \n\nGet those wands and put out the fires before the camp burns to ash!", progress = "We're fortunate that the Kul Tirans have a greater affinity for water than they do for fire.", completion = "Fire, blood, war. Nothing will stop us.", objectives = "Obtain a Fading Umbral Wand and use it to put out 4 flames around Warfang Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51675] = { id = 51675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunt Them Down", description = "These Kul Tirans, they don't seem normal. Humans can be a cruel bunch from what I've heard, but these ones seem to take pleasure in slaying the fallen. \n\nThe worst of them was a woman wearing a peculiar mask. She seemed to be shouting orders to the others, so I guess she's their leader.\n\nHonor the fallen and ensure they and their leader don't survive.", completion = "You've done us a great service, {name}.", objectives = "Slay Captain Ara and 8 Storm's Wake Footmen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51676] = { id = 51676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What a Gull Wants" }
quests[51677] = { id = 51677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mending Body and Soul", description = "Good. You have brought me the last ingredients I will need to concoct a solution to close the king's wounds.\n\nYou are not a moment too soon. He is fading.\n\nI am not comfortable working at an elevated pace, but the situation requires it. You must be my hands, for I am very slow.\n\nBring me what I need, and let Jamil and I worry about the rest.\n\nSpeak to me when you are ready to begin.", progress = "Stay on your toes. You have more of them than I do.", completion = "<Jol wheezes.>\n\nThat did not... work how I imagined it would.", objectives = "Follow Jol's directions to assist in healing King Rastakhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51678] = { id = 51678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rastakhan's Might", description = "Do you see de ship out in de bay, {name}?\n\nDat is my flagship, Rastakhan's Might. It is not here under my orders.\n\nWe will deal with de Prophet Zul in good time. For now, those who took my vessel must pay.\n\nYou are to bring me de head of Windcaller Ula'jan. De ship does not move without him, and it will not be moving again once he is dead!", progress = "Without de windcaller, my ship cannot be used to challenge my rule.", completion = "I will display dis behind my throne as a reminder. No one double-crosses Rastakhan and lives to speak of it.", objectives = "Collect Windcaller Ula'jan's skull aboard the flagship Rastakhan's Might.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51679] = { id = 51679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strange Port of Call", description = "I know Rastakhan is furious dat dey claimed his ship, of all de vessels in our navy.\n\nBut dere is a better question to ask. Why did dey bring it here?\n\nZeb'ahari is a small fishing village. Dere are no warriors here, no powerful supporters of de king. Dere must be another reason.\n\nBoard de ship and have a good look around. See if you can find out why dey brought dat beast of a boat way out here.", progress = "Did you learn anything, {name}?", completion = "I think I know what dis means, {name}, and it does not bode well for my loa.", objectives = "Search Rastakhan's Might for clues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51680] = { id = 51680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Bwonsamdi's Shadow", description = "Something is wrong, {name}.\n\nMy king is blessed by de loa in ways your kind cannot imagine. He has been given long life, swift healing, and strength beyond most trolls. But still, he lingers on death's door. I can practically hear Bwonsamdi laughing.\n\nTwo of his most trusted menders are with him. Go and find out what is taking so long.\n\nI will make sure dey are not interrupted.", completion = "Now you understand the precariousness of this situation. We will need your hands if we are to succeed in this complex bit of mending ahead of us.", objectives = "Speak to Jol the Ancient and Jamil Abul'housin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51681] = { id = 51681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basic Witch" }
quests[51682] = { id = 51682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Witches by the Dozen" }
