quests[51691] = { id = 51691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Almost Worth Saving", description = "We tried to evacuate as many of our people from the hold as we could, but some of the peons weren't so lucky. \n\nThey're worthless as fighters, but we'll need their labor in the times ahead.\n\nPlease, save them if you can.", completion = "Good work, {name}. We'll have need of their labor when we rebuild.", objectives = "Rescue 6 Frightened Peons from Warfang Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51693] = { id = 51693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intercepting the Irontide" }
