quests[51696] = { id = 51696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming What's Ours", description = "I'm impressed. You not only saved our people, but you also managed to kill the leader of the attacking forces.\n\nAt the top of this tower is our warhorn. At the signal, our troops will come running and we'll get this hold back under our control.\n\n{name}, I think you've earned the honors.", completion = "Good work, {name}\n\nMost of the buildings were easily repaired but we'll have to send to the Warchief for more troops.\n\nWe're going to have to fight for our place in this land... of this I'm certain.", objectives = "Sound the warhorn and retake control of Warfang Hold in Stormsong Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51697] = { id = 51697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting for Truffle Hunters" }
