quests[51711] = { id = 51711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Having a Blast", progress = "They won't stand a chance!", completion = "Sheesh... with all those explosions, I expect there's no one even left alive in that mine.", objectives = "Acquire a Bundle of Dynamite and use it to kill 16 Warfang Miners and 4 Mine Technicians.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51712] = { id = 51712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye for an Eye", progress = "Make them pay for what they've done to us.", completion = "I can't believe you actually pulled that off. We may actually stand a fighting chance now!", objectives = "Use the Prototype Shredder to burn 8 Warfang Buildings and kill General Blackstone and 30 Horde Soldiers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51714] = { id = 51714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission from the King", description = "Och, good ta see ya! Feels great ta stretch me gryphon's wings above the seas.\n\nI'm here ta assist with the war effort. Happy to help!\n\nLet's go meet with Master Shaw, matey.\n\nHa! Always wanted to say somethin' piratey. Did ya know they named a ship after me once? It was wild!", completion = "Good, we're all here. I asked for you by name, {name}. Falstad as well.", objectives = "Meet Spymaster Mathias Shaw on the Wind's Redemption.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51715] = { id = 51715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War of Shadows", description = "Every war is fought on multiple fronts, {class}.\n\nKing Wrynn has tasked Halford Wyrmbane and his 7th Legion with securing our position in Kul Tiras as well as Zandalar.\n\nBut they cannot succeed without us. We are the unseen hand. The shadows in the darkness.\n\nI have been charged with establishing an elite strike force, and I need you to act as liaison between Wyrmbane's efforts and my own.\n\nYou will help direct our missions going forward. Let us begin.", progress = "Without us, this war would be lost easily.", completion = "I am sure Falstad will handle this mission with his usual grace.", objectives = "Send Falstad on a mission.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51717] = { id = 51717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Best Honey In Vol'dun", description = "If you can handle rescuin' de others by yourself, Zulsan and I will head back to de inn and start cleanin' up de place.\n\nDon't worry, I still be cookin' up a special batch of my famous scorpid blood drinks for you.\n\nIn fact, you gonna be runnin' right past my friend Rikati. He sells de best honey in all of Vol'dun!\n\nBring back a few bottles of it for me and let's add some sweetness to de drinks!", completion = "Rhan'ka sent you? He still owes me for the last batch of honey I sold him!", objectives = "Meet Rikati at The Four Stingers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51718] = { id = 51718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harvesting \"Honey\"", description = "I don't know what Rhan'ka's doing down in that oasis with all of the honey he's bought from me. Frankly, I suspect I don't even want to know.\n\nBut whatever his reasons, Rhan'ka is my best customer.\n\nSo even though my supply's getting low, because Rhan'ka sent you, I'll give you a special deal.\n\nThe wasps here keep all their honey stored in their stingers. Bring some to me, so I can drain them for honey and I'll give you a big batch of the sticky stuff to take back to Rhan'ka.", progress = "Don't fret if some sand gets mixed in. It'll taste the same either way.", completion = "It'll just take me a moment to get the honey out of these.", objectives = "Collect 12 Bilewing Stingers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51719] = { id = 51719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Glaive Mistake" }
quests[51720] = { id = 51720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Shredded", description = "I was scouting ahead while you were wreaking havoc in the mine.\n\nSpotted a hulking, armored shredder in their lumber yard. Bet we could do some real damage with that thing! \n\nI tried to start it up, but looks like it might be out of juice. Maybe they forgot to charge it?\n\nSee if you can grab a fresh power core from one of the other shredders nearby.", progress = "<Energized Core required.>", completion = "<As the key clicks into place and the new core activates, a low hum begins emitting from the shredder. It accelerates into a high pitched whirring as the instrument panels light up all over the cockpit.>", objectives = "Find an Energized Power Core and install it in the Prototype Shredder MK-03.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51723] = { id = 51723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saw Dusted", description = "If we want to keep them from expanding into Stormsong, we need to cripple their lumber production!\n\nThey've only got so many lumberjacks running around. If we can cut some of them down, they'll be forced to reconsider their plans.", progress = "How many d'ya get?", completion = "Good work. That'll definitely put a damper on things.", objectives = "Kill 10 Warfang Lumberjacks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51726] = { id = 51726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Out of Here", description = "I can't believe you're here. Please, we need help!\n\nThey've been forcing us to mine nonstop. The weakest among us have been steadily dropping. At this rate, we'll all be dead soon.\n\nThe chains are weak. You may be able to pry the lock apart.\n\nI'll keep a lookout until the others are free. Don't worry about me!", progress = "Did you free everyone?", completion = "Thank you for rescuing us, we'd have been trapped in here until we all slowly perished.", objectives = "Free 6 Captured Miners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51727] = { id = 51727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shot at the Dark Iron" }
quests[51728] = { id = 51728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burn It All Down", description = "Alright, the flamethrower is all patched up. Now we're going to get a little payback for Brennadam!\n\nIf it's flammable, it's a target. If not, well, it probably still needs to die anyway. And let's bring down those siege towers while we're at it.\n\nBurn it all to the ground!", progress = "Well at least the flamethrower hasn't blown up on ya yet.", completion = "Nothing quite like the smell of freshly roasted Orc!", objectives = "Burn 6 Lumber Piles and 2 Siege Towers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
