quests[51751] = { id = 51751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation Royalty", completion = "I can't believe you actually pulled it off. We may actually stand a fighting chance now!", objectives = "Kill General Blackstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51752] = { id = 51752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grizzled", description = "I saw a particularly ugly and quite agitated goblin barking orders at the rest of the miners.\n\nI'm willing to bet he's crucial to their entire operation. If you can get into the mine and eliminate him, hopefully it will throw things into disarray.", completion = "Hopefully his death throws a wrench into their operation.", objectives = "Kill Chief Engineer Grizz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51753] = { id = 51753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Rexxar", objectives = "Through countless wars, I've learned that those who stand alone will fall.\n\nLet us stand as one, {name}. Together, we will face anything our foes send our way.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
