quests[51769] = { id = 51769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What a Gull Wants" }
quests[51770] = { id = 51770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission from the Warchief", description = "Lady Sylvanas issued orders for Garona Halforcen to take on a task of great import.\n\nShe will orchestrate missions from the Banshee's Wail, and is to assemble a strong force to execute on our plans.\n\nThis effort will be vital to our war against the Alliance, and your assistance will certainly be necessary.", completion = "Our task is not to be taken lightly, {name}.", objectives = "Walk with Garona Halforcen belowdecks on the Banshee's Wail.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51771] = { id = 51771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War of Shadows", description = "I have begun to assemble heroes for our cause. Perhaps you already know Arcanist Valtrois? We will need to recruit more in the future, but this is a promising beginning.\n\nOur missions will be those of subterfuge, reconnaissance, assassination, and other focused strikes against our enemies.\n\nLet us test the mettle of this nightborne, shall we?", progress = "I will not deviate from my mission.", completion = "Yes, this will do. The shadows will be stained blue with Alliance blood.", objectives = "Send Arcanist Valtrois on a mission.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51772] = { id = 51772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tortaka Tribe", description = "Have you ever met a tortollan before? Dey have all kinds of useful scrolls and artifacts for sale.\n\nWe used to trade often with de Tortaka tribe, but we haven't seen or heard from dem in weeks.\n\nDe tribe has a village in Darkwood Shoal. We need someone to make contact with dem and reestablish our trading partnership.", completion = "You're from the troll tribe at the arena? I'm afraid we don't have much to trade right now...", objectives = "Meet with Torka.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51773] = { id = 51773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ashvane Threat", description = "De Ashvane Trading Company has a mining operation in Redrock Harbor.\n\nDon't let de fancy name fool you, dey are as dangerous a band of pirates as I've ever seen.\n\nRecently, one of their crew members has been trying to make contact with us. I need someone to meet with him and see what he wants.\n\nIt might be a trap, but whatever information he has on de Ashvane Trading Company could prove useful to our survival.", completion = "You look like the kind of {race} that likes to make some coin. Am I wrong or am I right?", objectives = "Meet with Randall Redmond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51774] = { id = 51774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ragna" }
quests[51775] = { id = 51775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camp Lastwind", description = "A vulpera caravan recently set up camp not far from here.\n\nDis could be a good opportunity to establish new trade partners with de tribe.\n\nDe desert is a dangerous place, {name}. Go see if dey need any assistance. I'm sure dey could use experienced hands like yours.\n\nIn exchange, perhaps dey'd be willing to offer de tribe a discount on goods and services.", completion = "So you've come from the trolls at the arena and you're looking for work? I'd be happy to do business with you in exchange for a little help...", objectives = "Speak with Norah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51776] = { id = 51776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galestorm" }
quests[51777] = { id = 51777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dagrus the Scorned" }
quests[51778] = { id = 51778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deepfang" }
