quests[51781] = { id = 51781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foreman Scripps" }
quests[51782] = { id = 51782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Razorspine" }
quests[51783] = { id = 51783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zem'lan Rescue" }
quests[51784] = { id = 51784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Stroll Through a Cemetery", description = "Our next stop is in Drustvar.\n\nThere, along with some help, we shall identify and extract the body of a Kul Tiran war hero.\n\nWith his aid, we will learn much of the Kul Tiran fleet. Enough to break it with ease.\n\nWe shall meet you outside Barrowknoll Cemetery.\n\nDo try not to waste time, would you?", completion = "Ah {name}. You're here.\n\nYou remember Captain Stone, don't you? I think you shall find her quite a bit more... agreeable now.", objectives = "Meet Nathanos Blightcaller outside Barrowknoll Cemetery. \n\nDread-Admiral Tattersail can bring you to Drustvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51785] = { id = 51785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Examining the Epitaphs", description = "Without Stone's knowledge, this mission shall require some extra legwork.\n\nRead the plaques in the cemetery. Find the corpse of the most import.\n\nThe rest should be quite simple.", completion = "Marshal M. Valentine... yes, that name rings a bell. In a locked crypt, you say?\n\nThere are ways around that.", objectives = "Examine 4 Grave Plaques in Barrowknoll Cemetery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51786] = { id = 51786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "State of Unrest", description = "There is one thing you should know about ghosts, {name}.\n\nThey are a mockery of the dead. Spirits, holding on although they have no hope. In that form, they shall never truly live again. Not as long as they keep haunting our world.\n\nBut if they return to their bodies, perhaps they will become of specific use to us someday down the line.\n\nPut those spirits down.", completion = "Perhaps we shall have use for these people one day.\n\nSurely they will be thankful.", objectives = "Kill 8 Enraged Spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51787] = { id = 51787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Lot in Life", description = "It seems that Amalia isn't taking to undeath well.\n\nI know an herb that may help.\n\nThis cemetery is crawling with gravebloom. For the living, it grants the ability to see spirits.\n\nAs for the undead...\n\nThis may tie her back to reality just enough to be... sane.", progress = "What Amalia is going through... is familiar to me. She will learn how to embrace her new status as Forsaken.\n\nI will help.", completion = "Ah yes... in perfect condition.\n\nThis should do the trick.", objectives = "Collect 10 Gravebloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51788] = { id = 51788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crypt Keeper", description = "I've been keeping my sights on the cemetery.\n\nThere is one ghost that walks with a purpose, unlike the others.\n\nHe is the crypt keeper, the keeper of the keys.\n\nIf we want to get to Valentine's body, we will need to go through the ghost first.", progress = "Nothing can stand in our way. Not today.", completion = "Only one thing left to do.", objectives = "Collect Valentine's Key from Brutus Thornton.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51789] = { id = 51789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Remains of Marshal M. Valentine", description = "We have the key. We found the crypt.\n\nNext, Valentine's body shall be ours.\n\nNo need to wait for Lilian and Stone. Let's finish this now.", progress = "No time to dally. We have plans to enact.", completion = "Another inconvenience. At least Stone finally proved herself useful.", objectives = "Assist Nathanos Blightcaller in retrieving Valentine's body.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51791] = { id = 51791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bubbling Totem Testing" }
quests[51792] = { id = 51792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erupting Totem Testing" }
quests[51793] = { id = 51793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bubbling Totem Testing" }
quests[51794] = { id = 51794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erupting Totem Testing" }
quests[51795] = { id = 51795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Lordaeron", description = "King Wrynn has mustered our forces, {name}. We mean to launch a full-scale assault on Lordaeron.\n\nWe'll drive the Horde from the keep and reclaim it for the Alliance. It's been far too long since our flag flew in Tirisfal.\n\nReady to ship out? Captain Angelica here will see to your transport.", completion = "Ah, good to see you back on your feet, {name}. Many others were not so fortunate.\n\n\n\nKing Anduin has returned to Stormwind Keep. He must plan what our next move will be.", objectives = "Complete the Battle for Lordaeron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51796] = { id = 51796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Lordaeron", description = "The Alliance has called its banners and marches on the Undercity.\n\nNow the war has truly begun.\n\nOur mage will send you on your way. Go.\n\nSee to our defenses, and get the civilians to safety. I will join you soon.\n\nLok-tar ogar, {name}.", progress = "The High Overlord awaits.", completion = "Our war has only begun.", objectives = "Complete the Battle for Lordaeron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51797] = { id = 51797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Tidesages", description = "Rexxar has been tracking a powerful tidesage to help us find the body of Marshal Valentine. He has sent word of a breakthrough.\n\nTravel to Stormsong. Help the half-ogre and Lilian find this tidesage, and bend him to the will of the Horde.\n\nDo not come back without a way to find Marshal Valentine.", completion = "{name}. I'm aware of what the Horde needs. Let's get started.", objectives = "Meet Rexxar within Warfang Hold in Stormsong.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51798] = { id = 51798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Price Too High", description = "I have tracked a tidesage to a camp nearby. He has been staying there with his family.\n\nBe warned, tidesages are powerful foes. They have mastery over all the elements, and some even manipulate the Void.\n\nIf this man is with his family, it means he may not give up so easily. \n\nLet us hope he's smart enough to keep them out of this.\n\nCome.", completion = "Let's hope this tidesage is telling the truth or else it's about to get very bloody.", objectives = "Help Rexxar track down a tidesage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51800] = { id = 51800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foothold: Tiragarde Sound", description = "Tiragarde Sound has lotsa pirates on da coastline.\n\nI made contact wit' a first mate of a crew, and she tinks we can take on da captain and get a nice outpost in de process.\n\n          - Shadow Hunter Ty'jin", objectives = "Assist Shadow-Hunter Ty'jin in Tiragarde Sound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51801] = { id = 51801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foothold: Drustvar", description = "It seems Drustvar has a big seam of Azerite underground.\n\nDo you like profit? I LOVE profit. This seems like a golden opportunity, if ya catch my meanin'. Time is money!\n\n          - Trade Prince Gallywix", completion = "You have chosen to sail to Drustvar.", objectives = "Assist Gallywix and Eitrigg in Drustvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51802] = { id = 51802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foothold: Stormsong Valley", description = "We established and fortified an outpost in Stormsong Valley called Warfang Hold.\n\nThe Kul Tiran forces have it surrounded and an attack is imminent. We need reinforcements. Do not delay.\n\n                                 - Rexxar", sourceObjective = "Assist Rexxar in Stormsong Valley.", sourceObjectiveStatus = "unverified-source-field" }
quests[51803] = { id = 51803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kul Tiras Campaign", description = "Our enemy spreads its influence throughout Kul Tiras, recruiting new allies to fight against the Horde.\n\nWe must establish footholds in these enemy lands if we are to win this war.\n\nThe Warchief requires your assistance in securing outposts in Stormsong Valley, Drustvar, and Tiragarde Sound.\n\nWhich location shall we secure first?", completion = "You have the Queen's trust. For now.", objectives = "Use the Kul Tiras Campaign Map to choose a foothold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51804] = { id = 51804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Running Interference" }
quests[51805] = { id = 51805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Will Know Fear", description = "Finally, a chance to strike at the Alliance AND Kul Tirans!\n\nSagehold is crawling with initiate tidesages studying magic and Kul Tirans trying to fortify the place against the Horde.\n\nLet's strike some fear into them. Make them rethink trying to help the Alliance fight the Horde.\n\nTake this horn. In my hands, it calls a val'kyr. In yours, it will sow terror amongst our enemies.\n\nI trust you above all others with this horn. Do not let me down.", completion = "I could hear their screams from here! Maybe now the Kul Tirans will rethink helping the Alliance.", objectives = "Terrorize 20 Kul Tiran Builders or Tidesage Recruits with the Val'kyr Horn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51806] = { id = 51806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pest Remover Mk. II" }
quests[51810] = { id = 51810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Hartford", description = "I'm almost ready to leave Vol'dun once and for all. There's just one thing left to be done...\n\nWe need to murder the captain of the ship.\n\nIf Captain Hartford finds out I've deserted, I won't be safe in Boralus or anywhere else. He'll hunt me to the Eastern Kingdoms and back if he has to!\n\nThis will be dangerous. So you'll want to disguise yourself before boarding The Siren's Call.\n\nThis will be our last job together. Do it and I'll give you the code to the captain's lockbox. A pirate's bounty!", completion = "A toast to the former captain of The Siren's Call. He was a good man, but good men don't live long around here!", objectives = "Slay Captain Hartford.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51811] = { id = 51811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trapped Tortollans" }
quests[51813] = { id = 51813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackrock Depths", description = "Have you heard how the Dark Iron dwarves joined the Alliance? It was a most unusual turn of events.\n\nBrave heroes of the Alliance had been fighting the Dark Iron dwarves for years until a schism happened in their ranks.\n\nMoira Thaurissian, estranged daughter of the former dwarven king Magni Bronzebeard, was leading a faction of the Dark Iron dwarves.\n\nMoira wished to aid the Alliance. This began with an offer to help research Azerite and its potential uses within Blackrock Depths...", progress = "The mind o' a {race} is a glorious thing.", completion = "Meddlin' goblin bastards!\n\n<Moira takes a deep breath.>\n\nSorry, I just canna abide those green miscreants any longer.", objectives = "Speak with Moira at the Stormwind Embassy to travel to Blackrock Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51814] = { id = 51814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ravoracious" }
