quests[51817] = { id = 51817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trapped Tortollans" }
quests[51818] = { id = 51818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Commander and Captain", description = "This brings me no joy, {name}, but I will do what I must to make sure my family is happy and safe.\n\nI would prefer we avoid violence, but if we must... there are two targets. Their leaders. Captain Malia and Commander Augustine.\n\nTheir loss should force the two groups to retreat from the area. \n\nAlso, Augustine confiscated a book of mine. Recover it and my powers are yours, for however long I have left.", progress = "I don't need the details of what happened down there. Just the book.", completion = "I won't dwell on the grim task you've done. But I will show you just what this dying man is capable of, now that I have my book.", objectives = "Kill Captain Malia and recover the Book of Forbidden Magics from Commander Augustine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51819] = { id = 51819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scattering Our Enemies", description = "We've been scouting the area of Sagehold for some time now. It was recently retaken by a large force of Alliance and Kul Tirans.\n\nWe have been waiting for an opportunity to strike when their defenses were weakened. Now is that time.\n\nGo down to Sagehold and show the forces that remain what happens to those who take up arms against the Horde.", completion = "Good. The area of Sagehold should be overrun again by the rebel tidesages once we are done.", objectives = "Kill 10 Alliance and Kul Tiran soldiers within Sagehold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
