quests[51837] = { id = 51837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whatever Will Be", description = "Well, here we are. Zelling seems like he'll be a powerful asset, as long as we ensure his family is taken care of.\n\nHe doesn't have much time left. Let's see if he can locate Marshal Valentine for us before he passes.", progress = "Well?", completion = "We had best get moving. As much as I want this to turn out differently... odds are it won't.", objectives = "Get Zelling to locate Marshal Valentine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
