quests[51845] = { id = 51845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storm's End", description = "I've no doubt he can feel our presence, but so long as Lord Stormsong maintains his spell the first move is ours. \n\nWe have him surrounded, cornered like the rat he is. We must end this together.", completion = "Samuel was a good man, with a true heart. A fool... but our fool.", objectives = "Confront Lord Stormsong.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
