quests[51870] = { id = 51870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Island Expedition", description = "Our spies have intercepted an Alliance message describing an outcropping of Azerite out in the Great Sea.\n\nThe Banshee's Wail isn't quick enough to get us there before they do. Lucky for us, I've arranged to have a Zandalari ship rigged and ready to go for opportunities like this.\n\nGo speak with Captain Rez'okun on the western side of the docks. He's been briefed, and should be waiting for you.", completion = "You da Horde champion I'm waitin' for? Let's get to work.", objectives = "Report to Captain Rez'okun at the Port of Zandalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51874] = { id = 51874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorged Boar" }
quests[51881] = { id = 51881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mine Sweeper", description = "<One of the goblin flamethrowers. Unfortunately the tank has been cracked. It would be a good idea to bring it back to Felecia, she might have something to fix it up.>", completion = "A flamethrower!? This could be quite useful, but why couldn't you find one in better shape?", objectives = "Deliver the Cracked Mine Sweeper to Felecia Gladstone just outside the Saltstone Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
