quests[51888] = { id = 51888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Island Expedition", description = "We better be quick if we're gonna get to de island before de Alliance.\n\nYou ready?", progress = "Ready when you are.", completion = "Nice work, {name}. We make a good team. Let's do this again sometime.", objectives = "Speak with Captain Rez'okun to start the expedition, then explore the Uncharted Island.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51889] = { id = 51889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrath of Grapes", description = "You look familiar. Do you owe me money? Wait... no, that's not it.\n\nIf you are here to learn, I could show you my secret mining technique, bu- Ugh...\n\nI'm a little busy trying to see straight right now. Ugh... it feels like someone is swinging a pick at my skull. \n\nThe best cure for a hangover is pickle juice, a big greasy breakfast, and whatever I did not finish last night.\n\nTell you what, get me those things, preferably quickly and quietly, and I will teach you whatever ya want.", progress = "These shadows are loud. Can you fix that, too?", completion = "I needed this!\n\n<Franklin spends several moments shoveling food into his mouth.>\n\nMmm... Right! If I recall correctly, you were asking about storm silver seams?\n\nLet me tell you my secret technique, not even Myra knows. The metal is prone to stress fractures, but instead of scoring the metal where it meets the rock and breaking it off, just remove the rock.\n\nThe metal naturally forms prisms, and can be easily pulled out of the stone without wasting anything once it is loosened up.", objectives = "Bring a Jar of Pickle Juice, a Mountain of Bacon, a Pile of Sausages, and a Hillock of Eggs to Franklin The Drunk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51890] = { id = 51890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ranja the Last Chillpaw" }
