quests[51903] = { id = 51903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Island Expedition", description = "Our spies have intercepted a Horde message describing an outcropping of Azerite out in the Great Sea.\n\nThe Wind's Redemption isn't quick enough to get us there before they do. Lucky for us, I've arranged to have a Kul Tiran ship rigged and ready to go for opportunities like this.\n\nGo speak with Captain Flynn Fairwind. He's been briefed, and should be waiting for you.", completion = "Oh... you're the {class} I'm supposed to be waiting for? Let's get to work.", objectives = "Report to Flynn Fairwind in Boralus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[51904] = { id = 51904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Island Expedition", description = "Alright! Let's snap to it! We've got to get to that island before the Horde does, don't we?\n\nYou ready?", progress = "Ready when you are.", completion = "You and I make a pretty good team, don't we? Let's, uh, do this again sometime.", objectives = "Speak with Flynn Fairwind to start the expedition, then explore the Uncharted Island.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
